param([string]$PythonExe="",[string]$RepoRoot="D:\AssertionForge-main1",[string]$RelayUrl="https://api.highwayapi.ai/openai/chat/completions",[switch]$GenerateOnly)
$ErrorActionPreference="Stop";if(-not $PythonExe){$p=Join-Path $env:USERPROFILE ".cache\codex-runtimes\codex-primary-runtime\dependencies\python\python.exe";if(Test-Path $p){$PythonExe=$p}else{$PythonExe=(Get-Command python -ErrorAction Stop).Source}}
Set-Location -LiteralPath $RepoRoot;$names=@("OPENAI_API_KEY","ANTHROPIC_API_KEY","MULTIMODEL_OPENAI_BASE_URL","MULTIMODEL_OPENAI_MODEL","MULTIMODEL_CLAUDE_PROVIDER","MULTIMODEL_CLAUDE_BASE_URL","MULTIMODEL_CLAUDE_MODEL");$old=@{};foreach($n in $names){$old[$n]=[Environment]::GetEnvironmentVariable($n,"Process")};$secure=Read-Host "Highway API key" -AsSecureString;$ptr=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure)
try{$key=[Runtime.InteropServices.Marshal]::PtrToStringBSTR($ptr);$env:OPENAI_API_KEY=$key;$env:ANTHROPIC_API_KEY=$key;$env:MULTIMODEL_OPENAI_BASE_URL=$RelayUrl;$env:MULTIMODEL_OPENAI_MODEL="gpt-5.4";$env:MULTIMODEL_CLAUDE_PROVIDER="openai_compatible";$env:MULTIMODEL_CLAUDE_BASE_URL=$RelayUrl;$env:MULTIMODEL_CLAUDE_MODEL="claude-opus-4-8";$a=@("src/run_failure_guided_single_repair.py");if($GenerateOnly){$a+="--generate-only"};& $PythonExe @a;if($LASTEXITCODE -ne 0){throw "Failure-guided single repair failed with exit code $LASTEXITCODE"}}
finally{if($ptr-ne[IntPtr]::Zero){[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($ptr)};$key=$null;foreach($n in $names){[Environment]::SetEnvironmentVariable($n,$old[$n],"Process")}}
